const processedOrders = new Set(); // in real life this lives in a database, not memory

async function handleOrderPlaced(event) {
  if (processedOrders.has(event.orderId)) {
    return; // already handled this exact event, skip it
  }

  await reserveStock(event.items);
  processedOrders.add(event.orderId);
}

