const { Kafka } = require('kafkajs');
const kafka = new Kafka({ clientId: 'order-service', brokers: ['broker:9092'] });
const producer = kafka.producer();

async function publishOrderPlaced(order) {
  await producer.connect();
  await producer.send({
    topic: 'order-placed',
    messages: [
      {
        key: order.id,
        value: JSON.stringify({
          orderId: order.id,
          userId: order.userId,
          items: order.items,
          total: order.total
        })
      }
    ]
  });
}

